#!/bin/bash
# cloudpanel-mcp-gate.sh - SSH forced command for the cloudpanel-mcp-server key (OPTIONAL hardening).
#
# GENERATED by scripts/gen-gate.ts from the tool catalogue (npm run gen:gate). Edit only the
# settings block below; a test fails if the generated parts drift from the catalogue.
#
# What it is: sshd puts what the client asked to run into $SSH_ORIGINAL_COMMAND and runs THIS
# script instead (authorized_keys: command="/usr/local/sbin/cloudpanel-mcp-gate.sh",restrict ...).
# The script accepts exactly one shape and refuses everything else:
#
#   [sudo -n] /usr/bin/clpctl <command> '--name=value' '--name=value' ... ['--flag']
#
# (and, with nothing after it, the bare usage listing; and, when enabled, the inventory script)
#
# - <command> must be one of the commands cloudpanel-mcp-server has a tool for (a fixed list
#   below), in the class and scope this key may use;
# - every argument is ONE single-quoted token '--name=value' (or a declared flag), with a name that
#   command accepts, at most once, and every required one present;
# - every value must satisfy the same type the server applies (the RE_* lines are the very patterns
#   of src/validate/patterns.ts; test/gate.test.ts runs both on one corpus); files live in the
#   dumps/, certs/ or templates/ subdirectory of an allowed directory with that kind's extensions;
# - the whole line may only contain A-Z a-z 0-9 _ @ % + = : , . / space - [ ] and the single quote
#   ([ ] only for an IPv6 reverse-proxy URL): no ; & | < > ( ) $ ` \ " * ? { } ~ # ! newline or
#   control characters;
# - nothing is ever passed through a shell again: the arguments are parsed into an array and the
#   script exec's with that array.
#
# It never runs anything else: no shell, no other command, no interactive session.
# Needs bash 3.2 or newer.

set -u
set -f
IFS=$' \t\n'
LC_ALL=C
export LC_ALL
# Nothing the caller put in PATH is trusted; every program below is found here or named by a full path.
PATH=/usr/bin:/bin
export PATH

# ------------------------------------------------------------------------------------------
# Settings. Edit these lines; everything below is the logic.
# ------------------------------------------------------------------------------------------
# root: the key of the account that runs `sudo -n clpctl` (or is root). siteuser: the key of a
# SITE USER, which may only run the site-user commands, without sudo.
SCOPE=root
SUDO=/usr/bin/sudo
CLPCTL=/usr/bin/clpctl
# The ceiling this key can never exceed, whatever the MCP server is configured to do.
# Read-only commands are always allowed.
ALLOW_WRITE=1        # site:add:*, db:add, db:export, certificates, vhost templates, ...
ALLOW_DESTRUCTIVE=0  # site:delete, db:import, db:delete, vhost-template:delete
ALLOW_ADMIN=0        # user:*, cloudpanel:*:basic-auth, cloudpanel:set:release-channel, db:show:master-credentials
# The optional read-only inventory script (unofficial companion).
ALLOW_INVENTORY=0
INVENTORY=/usr/local/sbin/cloudpanel-mcp-inventory
# Server directories file parameters must live in; each kind of file has its own subdirectory:
# <dir>/dumps (*.sql, *.sql.gz), <dir>/certs (*.key, *.pem, ...), <dir>/templates (*.tpl, *.conf).
# Must match fileDirs of the MCP profile, and must be ROOT-OWNED: clpctl runs as root and follows symbolic links, so
# a directory any other account can write in lets that account redirect a dump or a certificate read to any file.
# The gate refuses to run with a directory in a system place or in a place other accounts usually write (/home, /tmp,
# /var/www, ...), unless ALLOW_UNTRUSTED_FILE_DIRS=1 (a throw-away test server only).
ALLOWED_FILE_DIRS=(/var/lib/cloudpanel-mcp-server)
ALLOW_UNTRUSTED_FILE_DIRS=0
# Hosts a reverse-proxy URL may point at. Must match proxyHosts of the MCP profile.
PROXY_HOSTS=(127.0.0.1 localhost ::1)
# Ports of Node.js and Python apps and of reverse-proxy upstreams: single ports and low-high ranges.
# Must match appPorts of the MCP profile. Database, cache and admin ports are refused whatever is listed.
APP_PORTS=(@@DEFAULT_APP_PORTS@@)
# Targets this key may never delete, overwrite, reset or reuse, whatever the MCP server says.
# Domains: exact, or *.suffix (which also covers the apex); a leading www. is ignored.
# Names are compared without regard to case.
PROTECT_DOMAINS=()
PROTECT_SITE_USERS=()
PROTECT_DATABASES=()
PROTECT_PANEL_USERS=()
# Send one line per accepted or refused command (command name only, never values) to syslog.
SYSLOG=1
# ------------------------------------------------------------------------------------------

@@GENERATED@@

# Shape of the command line itself.
RE_CHARS="^[]A-Za-z0-9_@%+=:,./ '[-]*\$"
RE_SUBCOMMAND='^([a-z][a-z0-9:-]{0,63})(.*)$'
RE_OPTION="^ '--([A-Za-z0-9]+)=([^']*)'(.*)\$"
RE_FLAG="^ '--([a-z][a-z-]{0,31})'(.*)\$"
RE_PORT='^[1-9][0-9]{0,4}$'
RE_PORT_ENTRY='^([0-9]{1,5})(-([0-9]{1,5}))?$'
RE_PROXY_HOST='^[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?$'
RE_PROXY_HOST6='^[0-9a-f:]{2,39}$'

log_line() {
  [[ $SYSLOG == 1 ]] || return 0
  command -v logger >/dev/null 2>&1 || return 0
  logger -p auth.notice -t cloudpanel-mcp-gate -- "$1" >/dev/null 2>&1 || true
}

refuse() {
  log_line "refused: $1"
  printf 'cloudpanel-mcp-gate: refused: %s\n' "$1" >&2
  exit 126
}

in_list() { # <needle> <item>...
  local needle=$1 item
  shift
  for item in "$@"; do
    [[ $item == "$needle" ]] && return 0
  done
  return 1
}

lower() {
  printf '%s' "$1" | tr 'A-Z' 'a-z'
}

in_list_ci() { # <needle> <item>...: the same without regard to case
  local needle item
  needle=$(lower "$1")
  shift
  for item in "$@"; do
    [[ $(lower "$item") == "$needle" ]] && return 0
  done
  return 1
}

valid_domain() {
  (( ${#1} <= 253 )) && [[ $1 =~ $RE_domain ]]
}

valid_domain_list() {
  local value=$1 part
  local -a parts
  (( ${#value} <= 5100 )) || return 1
  [[ -n $value && $value != ,* && $value != *, && $value != *,,* && $value != *$'\n'* ]] || return 1
  IFS=, read -r -a parts <<<"$value"
  (( ${#parts[@]} >= 1 && ${#parts[@]} <= 20 )) || return 1
  for part in "${parts[@]}"; do
    valid_domain "$part" || return 1
  done
  return 0
}

valid_path() { # <value> <subdirectory> <extension pattern>
  local value=$1 sub=$2 ext=$3 dir ok=1
  [[ $value =~ $RE_serverPath ]] || return 1
  [[ $value == *..* || $value == *//* || $value == */./* || $value == */ || $value == */. ]] && return 1
  for dir in ${ALLOWED_FILE_DIRS[@]+"${ALLOWED_FILE_DIRS[@]}"}; do
    if (( ${#value} > ${#dir} + ${#sub} + 2 )) && [[ $value == "$dir/$sub/"* ]]; then
      ok=0
      break
    fi
  done
  (( ok == 0 )) || return 1
  [[ $value =~ $ext ]]
}

# 0 when <port> is one the settings allow: above 1023, not a denied port, inside one of APP_PORTS.
# An entry that is not "port" or "low-high" allows nothing (fail closed).
valid_port() {
  local value=$1 denied entry low high
  [[ $value =~ $RE_PORT ]] || return 1
  (( value >= 1024 && value <= 65535 )) || return 1
  for denied in "${DENIED_PORTS[@]}"; do
    (( value == denied )) && return 1
  done
  for entry in ${APP_PORTS[@]+"${APP_PORTS[@]}"}; do
    [[ $entry =~ $RE_PORT_ENTRY ]] || continue
    low=${BASH_REMATCH[1]}
    high=${BASH_REMATCH[3]:-$low}
    (( 10#$value >= 10#$low && 10#$value <= 10#$high )) && return 0
  done
  return 1
}

# Sets URL_HOST, URL_PORT (empty when absent) and returns 0 for a well-formed URL.
parse_url() {
  local value=$1 path
  URL_HOST=
  URL_PORT=
  (( ${#value} <= 300 )) || return 1
  [[ $value =~ $RE_proxyUrl ]] || return 1
  URL_HOST=${BASH_REMATCH[2]}
  URL_PORT=${BASH_REMATCH[4]}
  path=${BASH_REMATCH[5]}
  URL_HOST=${URL_HOST#[}
  URL_HOST=${URL_HOST%]}
  if [[ -n $URL_PORT ]]; then
    URL_PORT=${URL_PORT#:}
    (( URL_PORT >= 1 && URL_PORT <= 65535 )) || return 1
    if (( URL_PORT != 80 && URL_PORT != 443 )); then
      valid_port "$URL_PORT" || return 1
    fi
  fi
  [[ $path == *..* || $path == *//* ]] && return 1
  return 0
}

valid_proxy_url() {
  parse_url "$1" || return 1
  in_list "$URL_HOST" ${PROXY_HOSTS[@]+"${PROXY_HOSTS[@]}"}
}

valid_purge() {
  local value=$1 part has_all=0
  local -a parts
  [[ $value == all ]] && return 0
  if [[ $value == http://* || $value == https://* ]]; then
    parse_url "$value" || return 1
    [[ -z $URL_PORT ]] || return 1
    valid_domain "$URL_HOST"
    return
  fi
  (( ${#value} <= 1300 )) || return 1
  [[ -n $value && $value != ,* && $value != *, && $value != *,,* && $value != *$'\n'* ]] || return 1
  IFS=, read -r -a parts <<<"$value"
  (( ${#parts[@]} >= 1 && ${#parts[@]} <= 20 )) || return 1
  for part in "${parts[@]}"; do
    [[ $part =~ $RE_cacheTag ]] || return 1
    [[ $part == all ]] && has_all=1
  done
  (( ${#parts[@]} == 1 || has_all == 0 )) || return 1
  return 0
}

bare_domain() { # every leading "www." is ignored (www.www.example.com would claim www.example.com)
  local d=$1
  while [[ $d == www.* ]]; do
    d=${d#www.}
  done
  printf '%s' "$d"
}

domain_protected() {
  local d entry suffix
  d=$(bare_domain "$(lower "$1")")
  for entry in ${PROTECT_DOMAINS[@]+"${PROTECT_DOMAINS[@]}"}; do
    entry=$(lower "$entry")
    if [[ $entry == \*.* ]]; then
      suffix=$(bare_domain "${entry#\*.}")
      [[ $d == "$suffix" || $d == *".$suffix" ]] && return 0
    else
      [[ $(bare_domain "$entry") == "$d" ]] && return 0
    fi
  done
  return 1
}

protected() { # <kind> <value>
  case $1 in
    domain) domain_protected "$2" ;;
    siteUser) in_list_ci "$2" ${PROTECT_SITE_USERS[@]+"${PROTECT_SITE_USERS[@]}"} ;;
    database) in_list_ci "$2" ${PROTECT_DATABASES[@]+"${PROTECT_DATABASES[@]}"} ;;
    panelUser) in_list_ci "$2" ${PROTECT_PANEL_USERS[@]+"${PROTECT_PANEL_USERS[@]}"} ;;
    *) return 1 ;;
  esac
}

under_root() { # <path> <root>...
  local path=$1 root
  shift
  for root in "$@"; do
    [[ $path == "$root" || $path == "$root"/* ]] && return 0
  done
  return 1
}

# A directory the settings name: a clean path at least two levels deep, in no system place and (unless allowed) in
# no place other accounts write. The same rules as the server's configuration.
valid_file_dir() {
  local dir=$1
  [[ $dir =~ $RE_serverPath ]] || return 1
  [[ $dir == *..* || $dir == *//* || $dir == */./* || $dir == */ || $dir == */. ]] && return 1
  [[ $dir =~ ^/[^/]+/[^/]+ ]] || return 1
  under_root "$dir" "${FORBIDDEN_DIR_ROOTS[@]}" && return 1
  if [[ $ALLOW_UNTRUSTED_FILE_DIRS != 1 ]]; then
    under_root "$dir" "${SHARED_DIR_ROOTS[@]}" && return 1
  fi
  return 0
}

# An APP_PORTS entry: "port" or "low-high" inside 1024-65535, low not above high; a single port the server never allows is refused outright.
valid_port_entry() {
  local entry=$1 low high denied
  [[ $entry =~ $RE_PORT_ENTRY ]] || return 1
  low=${BASH_REMATCH[1]}
  high=${BASH_REMATCH[3]:-$low}
  (( 10#$low >= 1024 && 10#$high <= 65535 && 10#$low <= 10#$high )) || return 1
  if [[ -z ${BASH_REMATCH[3]:-} ]]; then
    for denied in "${DENIED_PORTS[@]}"; do
      (( 10#$low == denied )) && return 1
    done
  fi
  return 0
}

# A setting that is not valid for its kind would silently protect nothing, or allow what the server never would (a
# trailing dot, a single-label host, an underscore in a domain, /tmp as a file directory): refuse to run instead.
# The same rules as the server's configuration.
check_settings() {
  local entry
  for entry in ${ALLOWED_FILE_DIRS[@]+"${ALLOWED_FILE_DIRS[@]}"}; do
    valid_file_dir "$entry" || refuse 'an ALLOWED_FILE_DIRS setting of the gate is not a usable directory (a clean path two levels deep, in no system place and no place other accounts write; make it root-owned)'
  done
  for entry in ${PROXY_HOSTS[@]+"${PROXY_HOSTS[@]}"}; do
    [[ $entry =~ $RE_PROXY_HOST || $entry =~ $RE_PROXY_HOST6 ]] || refuse 'a PROXY_HOSTS setting of the gate is malformed (a lowercase host name or an IPv6 address)'
  done
  for entry in ${APP_PORTS[@]+"${APP_PORTS[@]}"}; do
    valid_port_entry "$entry" || refuse 'an APP_PORTS setting of the gate is malformed (a port or low-high from 1024 to 65535, never a port the server refuses)'
  done
  for entry in ${PROTECT_DOMAINS[@]+"${PROTECT_DOMAINS[@]}"}; do
    entry=$(lower "$entry")
    entry=${entry#\*.}
    valid_domain "$entry" || refuse 'a PROTECT_DOMAINS setting of the gate is malformed (a lowercase domain name, or *.domain)'
  done
  for entry in ${PROTECT_SITE_USERS[@]+"${PROTECT_SITE_USERS[@]}"}; do
    [[ $(lower "$entry") =~ $RE_siteUser ]] || refuse 'a PROTECT_SITE_USERS setting of the gate is malformed'
  done
  for entry in ${PROTECT_DATABASES[@]+"${PROTECT_DATABASES[@]}"}; do
    [[ $entry =~ $RE_dbName ]] || refuse 'a PROTECT_DATABASES setting of the gate is malformed'
  done
  for entry in ${PROTECT_PANEL_USERS[@]+"${PROTECT_PANEL_USERS[@]}"}; do
    [[ $entry =~ $RE_panelUser ]] || refuse 'a PROTECT_PANEL_USERS setting of the gate is malformed'
  done
}

valid_value() { # <type> <value>
  local value=$2
  case $1 in
    domain) valid_domain "$value" ;;
    domainList) valid_domain_list "$value" ;;
    siteUser) [[ $value =~ $RE_siteUser ]] && ! in_list "$value" "${RESERVED_SITE_USERS[@]}" ;;
    dbUser) [[ $value =~ $RE_dbUser ]] && ! in_list "$(lower "$value")" "${RESERVED_DB_USERS[@]}" ;;
    userDbName) [[ $value =~ $RE_dbName ]] && ! in_list "$(lower "$value")" "${RESERVED_DATABASES[@]}" ;;
    email) (( ${#value} <= 254 )) && [[ $value =~ $RE_email ]] ;;
    port) valid_port "$value" ;;
    dumpPath) valid_path "$value" "$SUBDIR_dump" "$RE_EXT_dump" ;;
    certPath) valid_path "$value" "$SUBDIR_cert" "$RE_EXT_cert" ;;
    templatePath) valid_path "$value" "$SUBDIR_template" "$RE_EXT_template" ;;
    proxyUrl) valid_proxy_url "$value" ;;
    purge) valid_purge "$value" ;;
    role) in_list "$value" admin site-manager user ;;
    status) in_list "$value" 0 1 ;;
    channel) in_list "$value" stable test ;;
    password) [[ $value =~ $RE_generatedPassword ]] ;;
@@PATTERN_CASES@@
    *) return 1 ;;
  esac
}

# type_of <name>: prints the type of the option <name> for the current command.
type_of() {
  local pair
  for pair in $REQ $OPT; do
    if [[ ${pair%%:*} == "$1" ]]; then
      printf '%s' "${pair#*:}"
      return 0
    fi
  done
  return 1
}

flag_allowed() {
  local flag
  for flag in $FLG; do
    [[ $flag == "$1" ]] && return 0
  done
  return 1
}

USE_SUDO=0
do_exec() {
  if [[ $USE_SUDO == 1 ]]; then
    exec "$SUDO" -n "$@"
  fi
  exec "$@"
}

main() {
  check_settings
  local cmd=${SSH_ORIGINAL_COMMAND-}
  [[ -n $cmd ]] || refuse 'interactive sessions and empty commands are not allowed'
  (( ${#cmd} <= 4096 )) || refuse 'command too long'
  [[ $cmd =~ $RE_CHARS ]] || refuse 'the command contains a character that is never allowed'

  local rest=$cmd
  if [[ $rest == 'sudo -n '* ]]; then
    [[ $SCOPE == root ]] || refuse 'sudo is not allowed for this key'
    USE_SUDO=1
    rest=${rest#'sudo -n '}
  fi

  if [[ $rest == "$INVENTORY" ]]; then
    [[ $SCOPE == root && $ALLOW_INVENTORY == 1 ]] || refuse 'the inventory script is not enabled in this gate'
    log_line 'accepted: inventory'
    do_exec "$INVENTORY"
  fi

  if [[ $rest == "$CLPCTL" ]]; then
    [[ $SCOPE == root ]] || refuse 'the usage listing is not allowed for this key'
    log_line 'accepted: usage listing'
    do_exec "$CLPCTL"
  fi
  [[ $rest == "$CLPCTL "* ]] || refuse 'only the clpctl program is allowed'
  rest=${rest#"$CLPCTL "}

  [[ $rest =~ $RE_SUBCOMMAND ]] || refuse 'malformed command'
  local sub=${BASH_REMATCH[1]}
  rest=${BASH_REMATCH[2]}
  spec_lookup "$sub" || refuse "the command $sub is not allowed"
  [[ $CMD_SCOPE == "$SCOPE" ]] || refuse "the command $sub is not allowed for this key"
  if [[ $SCOPE == siteuser ]]; then
    # a site user's commands carry no user name: the key's own account is the target
    local me
    me=$(id -un 2>/dev/null) || refuse 'cannot tell which site user this key belongs to'
    # a site-user gate in root's or a system account's authorized_keys would run these commands as that account
    [[ $(id -u 2>/dev/null) != 0 ]] || refuse 'a site-user gate does not run as root'
    if in_list "$me" "${RESERVED_SITE_USERS[@]}"; then
      refuse 'a site-user gate does not run as a system account'
    fi
    if protected siteUser "$me"; then
      refuse 'this site user is protected in this gate'
    fi
  fi

  case $CLASS in
    read) ;;
    write) [[ $ALLOW_WRITE == 1 ]] || refuse "$sub is write-class and ALLOW_WRITE=0 in the gate" ;;
    destructive) [[ $ALLOW_WRITE == 1 && $ALLOW_DESTRUCTIVE == 1 ]] || refuse "$sub is destructive and ALLOW_DESTRUCTIVE=0 in the gate" ;;
    admin) [[ $ALLOW_WRITE == 1 && $ALLOW_ADMIN == 1 ]] || refuse "$sub is admin-class and ALLOW_ADMIN=0 in the gate" ;;
    *) refuse 'internal error: unknown class' ;;
  esac

  local -a args=()
  local seen=' ' name value type pair kind varname
  while [[ -n $rest ]]; do
    if [[ $rest =~ $RE_OPTION ]]; then
      name=${BASH_REMATCH[1]}
      value=${BASH_REMATCH[2]}
      rest=${BASH_REMATCH[3]}
      type=$(type_of "$name") || refuse "the option --$name is not allowed for $sub"
      [[ $seen != *" $name "* ]] || refuse "the option --$name is given twice"
      valid_value "$type" "$value" || refuse "the value of --$name is not valid"
      seen+="$name "
      printf -v "ARG_$name" '%s' "$value"
      args+=("--$name=$value")
    elif [[ $rest =~ $RE_FLAG ]]; then
      name=${BASH_REMATCH[1]}
      rest=${BASH_REMATCH[2]}
      flag_allowed "$name" || refuse "the flag --$name is not allowed for $sub"
      [[ $seen != *" $name "* ]] || refuse "the flag --$name is given twice"
      seen+="$name "
      args+=("--$name")
    else
      refuse 'malformed argument (every argument must be one single-quoted token)'
    fi
  done

  for pair in $REQ; do
    [[ $seen == *" ${pair%%:*} "* ]] || refuse "the required option --${pair%%:*} is missing"
  done

  # rules between options
  if [[ $sub == user:add && $seen == *' sites '* && ${ARG_role-} != user ]]; then
    refuse 'sites can only be set when role is user'
  fi

  # protected targets; a list option (domains) is checked one entry at a time
  # The list is split with parameter expansion only: a here-string needs a temporary file or a pipe, and if that
  # could not be made the check would see no entries and let everything through.
  local part rest
  for pair in $PROT; do
    name=${pair%%:*}
    kind=${pair#*:}
    [[ $seen == *" $name "* ]] || continue
    varname="ARG_$name"
    rest="${!varname},"
    while [[ -n $rest ]]; do
      part=${rest%%,*}
      rest=${rest#*,}
      if protected "$kind" "$part"; then
        refuse "the target of --$name is protected in this gate"
      fi
    done
  done

  log_line "accepted: $sub"
  do_exec "$CLPCTL" "$sub" ${args[@]+"${args[@]}"}
}

main
